// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // RLP-encode [sender, nonce] (nonce assumed < 0x80, payload short form) and
    // derive the CREATE address of the next contract deployed by `sender`.
    function predictCreate(address sender, uint256 nonce) internal pure returns (address) {
        bytes1 nb = nonce == 0 ? bytes1(0x80) : bytes1(uint8(nonce));
        bytes memory rlp = abi.encodePacked(hex"d694", sender, nb);
        return address(uint160(uint256(keccak256(rlp))));
    }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Grant admin rights to the fuzzed actor if the contract exposes a setter;
        // a harmless no-op (caught revert) if it does not.
        (bool adminOk,) = address(c).call(
            abi.encodeWithSignature("setAdmin(address)", actor)
        );
        if (!adminOk) {
            // Fall back: try the direct mapping-style names, ignore failure.
            address(c).call(abi.encodeWithSignature("setIsAdmin(address,bool)", actor, true));
        }

        uint256 nonceBefore = address(c).nonce;
        address predictedOracle = predictCreate(address(c), nonceBefore);

        vm.prank(actor);
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("newEmergencyOracle(string)", description)
        );

        // General rule: whenever the call succeeds, the oracle created by c must be
        // owned by the CALLING actor (msg.sender), never by address(c) itself.
        if (ok) {
            assertTrue(
                IEmergencyOracle(predictedOracle).owner() == actor,
                "oracle owner must be the calling actor"
            );
        } else {
            // If the call reverts (e.g. actor not admin), nothing to check.
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface EmergencyOracleLike {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    uint256 oracleNonce;

    function setUp() public { c = new C(); oracleNonce = 0; }

    function testFuzz_property(string memory description) public {
        // compute the address where CREATE from c will place the new oracle
        address predicted = address(
            uint160(
                uint256(
                    keccak256(
                        abi.encodePacked(
                            bytes1(0xd6),
                            bytes1(0x94),
                            address(c),
                            uint8(oracleNonce)
                        )
                    )
                )
            )
        );

        // the admin/deployer drives the entry point
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            oracleNonce += 1;
        }

        // GENERAL RULE: whenever the oracle is created, it is owned by the
        // calling account, never by the factory contract itself.
        assertTrue(
            !ok || EmergencyOracleLike(predicted).owner() == address(this),
            "new EmergencyOracle must be owned by the caller"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracleOwner {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, string calldata description) public {
        // Wide admissible domain: any caller distinct from the factory itself.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(bytes(description).length < 256);

        // Drive c through its public entry; the call may revert (non-admin) — that is fine.
        vm.prank(actor);
        try c.newEmergencyOracle(description) {
            // call succeeded
        } catch {
            // call reverted; oracle may not exist
        }

        // Deterministically derive the address of the first contract created by c
        // (c is freshly deployed in setUp, so its first CREATE uses nonce 1).
        // RLP([sender, 1]) = 0xd6 0x94 <sender20> 0x01
        bytes memory rlp = abi.encodePacked(hex"d694", address(c), hex"01");
        address oracle = address(uint160(uint256(keccak256(rlp))));

        // Observe the deployed oracle's ownership surface (owner() getter).
        address oracleOwner;
        (bool ok, bytes memory ret) = oracle.staticcall(
            abi.encodeWithSelector(IOracleOwner.owner.selector)
        );
        if (ok && ret.length == 32) {
            oracleOwner = abi.decode(ret, (address));
        }

        // General rule: an oracle minted by c is never owned by the factory contract
        // address(c) itself; in the reference it is owned by the calling account
        // (distinct from address(c) by assumption), or is absent (owner reads as 0).
        // The mutant sets the oracle's owner to address(this) == address(c),
        // breaking the rule for every admissible input that deploys an oracle.
        assertTrue(oracleOwner != address(c));
    }
}

