pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOwnable {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address admin, string calldata description) public {
        // 1. Keep the domain wide; only exclude inputs that cannot distinguish the bug.
        vm.assume(admin != address(0));
        vm.assume(admin != address(c));

        // 2. Grant admin rights (best effort via low-level call so it compiles
        //    regardless of the exact setter signature on C).
        address(c).call(abi.encodeWithSignature("setAdmin(address,bool)", admin, true));

        // Predicted address of the first contract created by c (create1, nonce 1).
        bytes memory rlp = abi.encodePacked(hex"d694", address(c), hex"01");
        address predicted = address(uint160(uint256(keccak256(rlp))));

        // Drive c through the boundary entry.
        vm.prank(admin);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. General rule: whenever the oracle is successfully deployed, it is
        //    owned by the calling admin — never by address(c). If no deployment
        //    happened the oracle address has no code and owner() returns 0.
        assertTrue(
            !ok || IOwnable(predicted).owner() == admin,
            "deployed EmergencyOracle must be owned by the calling admin"
        );
    }
}

