pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface EmergencyOracleLike {
    function turnOnOracle() external;
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Best-effort: attempt common admin-enabling entry points on c.
    function _enableAdmin(address a) internal returns (bool) {
        (bool s1,) = address(c).call(abi.encodeWithSignature("setAdmin(address,bool)", a, true));
        if (s1) return true;
        (bool s2,) = address(c).call(abi.encodeWithSignature("setIsAdmin(address,bool)", a, true));
        if (s2) return true;
        (bool s3,) = address(c).call(abi.encodeWithSignature("addAdmin(address)", a));
        if (s3) return true;
        (bool s4,) = address(c).call(abi.encodeWithSignature("grantAdmin(address)", a));
        return s4;
    }

    // Compute the address of the Nth contract created by `deployer` (CREATE semantics).
    function _predictCreate(address deployer, uint8 nonceByte) internal pure returns (address) {
        bytes memory rlp = abi.encodePacked(hex"d6", hex"94", bytes20(deployer), nonceByte);
        return address(uint160(uint256(keccak256(rlp))));
    }

    function testFuzz_property(address actor, string memory description) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(bytes(description).length > 0 && bytes(description).length <= 64);

        _enableAdmin(actor);

        // Drive c through newEmergencyOracle.
        bool ok = false;
        vm.prank(actor);
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {}

        if (ok) {
            // The oracle created by c is the first contract c ever creates (nonce 0).
            address predicted = _predictCreate(address(c), hex"80");
            bool usable = false;
            vm.prank(actor);
            try EmergencyOracleLike(predicted).turnOnOracle() {
                usable = true;
            } catch {}
            // GENERAL RULE: any oracle created by c is operable by the account that created it.
            assertTrue(!ok || usable);
        } else {
            // If creation did not occur, the rule is vacuously satisfied for this input.
            assertTrue(!ok);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // RLP-encoded create address for origin at small nonce (nonce < 128, here nonce == 1)
    function _createAddress(address origin, uint256 nonce) internal pure returns (address) {
        require(nonce < 128, "nonce too big");
        bytes memory buf = new bytes(24);
        buf[0] = 0xd6;
        buf[1] = 0x94;
        for (uint256 i = 0; i < 20; i++) {
            buf[2 + i] = bytes20(origin)[i];
        }
        buf[22] = bytes1(uint8(nonce));
        buf[23] = 0x80;
        return address(uint160(uint256(keccak256(buf))));
    }

    function testFuzz_property(address admin, string memory desc) public {
        // wide admissible domain: any non-zero admin distinct from c, any description
        vm.assume(admin != address(0));
        vm.assume(admin != address(c));
        vm.assume(bytes(desc).length > 0);

        // grant admin (slot 0 is the isAdmin mapping in C)
        bytes32 slot = keccak256(abi.encode(admin, uint256(0)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        // drive c through newEmergencyOracle
        vm.prank(admin);
        bool ok;
        try c.newEmergencyOracle(desc) {
            ok = true;
        } catch {
            ok = false;
        }

        // the first contract created by c lands at the nonce-1 create address
        address oracle = _createAddress(address(c), 1);

        // read the deployed oracle's public description()
        (bool okd, bytes memory ret) = oracle.staticcall(abi.encodeWithSignature("description()"));
        assertTrue(ok && okd && keccak256(ret) == keccak256(abi.encode(desc)), "oracle description must equal caller-supplied description");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(string calldata description) external {
        // The test contract has never been granted admin rights.
        require(!c.isAdmin(address(this)), "caller must be a non-admin");

        bool callSucceeded = true;
        try c.newEmergencyOracle(description) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        // General rule: a call to newEmergencyOracle succeeds if and only if
        // the caller is an admin. A non-admin call must revert.
        assert(callSucceeded == c.isAdmin(address(this)));
    }
}
